####### Funktion, um das aktuelle Jahr und Quartal zu bestimmen
Quartal_bestimmen <- function(){

  #Datum <- as.Date('2026-01-01')
  #print(Datum)

  if(Sys.Date() >= as.Date(paste0(lubridate::year(Sys.Date()),'-01-01')) && Sys.Date() < as.Date(paste0(lubridate::year(Sys.Date()),'-04-01'))){
    Quartal_fill <- "1. Quartal"
  } else if(Sys.Date() >= as.Date(paste0(lubridate::year(Sys.Date()),'-04-01')) && Sys.Date() < as.Date(paste0(lubridate::year(Sys.Date()),'-07-01'))){
    Quartal_fill <- "2. Quartal"
  } else if(Sys.Date() >= as.Date(paste0(lubridate::year(Sys.Date()),'-07-01')) && Sys.Date() < as.Date(paste0(lubridate::year(Sys.Date()),'-10-01'))){
    Quartal_fill <- "3. Quartal"
  } else {
    Quartal_fill <- "4. Quartal"
  }

  Jahr_fill <- as.character(lubridate::year(Sys.Date()))
  Quartal_mapping <- data.frame(Quartal = c("1. Quartal", "2. Quartal", "3. Quartal", "4. Quartal"), Before = c("4. Quartal", "1. Quartal", "2. Quartal", "3. Quartal"), After=c("2. Quartal", "3. Quartal", "4. Quartal", "1. Quartal"))
  Quartal_bef <- Quartal_mapping$Before[match(Quartal_fill, Quartal_mapping$Quartal)]
  Jahr_bef <- as.character(lubridate::year(Sys.Date())-1)

  ### Was soll das überhaupt und macht das Sinn??? -> Nachrpüfen!!
  if(Quartal_bef == "4. Quartal"){
    Jahr_fill2 <- as.character((as.integer(Jahr_fill)-1))
  } else { Jahr_fill2 = Jahr_fill}

  ## first select for input filter:
  first_select <- paste0(Jahr_fill2, ": ", Quartal_bef)

  return(list(Quartal_fill, Jahr_fill, Quartal_mapping, Quartal_bef, Jahr_bef, Jahr_fill2, first_select))

}


