### custom function to update / insert data in a batch


db_update <- function(conn, SQL_table, df, key, aenddate){

  # create a temporary table on SQL server to insert the data
  temp <- paste0("#", SQL_table)
  DBI::dbWriteTable(conn, temp, df, temporary = TRUE, overwrite = TRUE)

  # construct SQL statement
  update_columns = setdiff(names(df), c(key,aenddate))
  set_clause = paste(
    sprintf("%s = %s.%s", update_columns, temp, update_columns),
    collapse = " ,"
  )

  sql_query = glue::glue_sql(
    "UPDATE {`SQL_table`}
    SET {SQL(set_clause)}
    FROM {`temp`}
    WHERE {`SQL_table`}.{`key`} = {`temp`}.{`key`}", # optimistic concurrency , noch testen und ggf. warnen, wenns nicht funktioniert hat?
    .con = conn
  )

  DBI::dbExecute(conn, sql_query)
  DBI::dbExecute(conn, glue::glue_sql("DROP TABLE {`temp`}", .con = conn))

  message("Batch update completed")
}


## Funktion zum gezielten Löschen von bereis angelegten Zeilen

db_delete <- function(conn, SQL_table, vec){

  del_list <- paste(sprintf("%s", vec), collapse = ", ")
  sql_query = glue::glue_sql(
   "DELETE FROM {`SQL_table`}
    WHERE kid IN ({SQL(del_list)})", .con = conn
  )

  DBI::dbExecute(conn, sql_query)
  message("Delete successful")
}

