# Helper function for comparing übernommene Daten mit den alten Daten -> wichtige Merkmale gleich? Stellen-id kann bleiben - sonst: set to NA (neue muss bestimmt werden)
get_new_stellen_id_range <- function(conn, n) {
  ### the stored procedure reserves the bulked values - no other use can have them now -> safe against concurrency!

  stell_range <- dbGetQuery(conn, paste0("
    DECLARE @first SQL_VARIANT;
    EXEC sp_sequence_get_range
        @sequence_name     = N'dbo.stellen_id_seq',
        @range_size        = ", n,",
        @range_first_value = @first OUTPUT;
    SELECT CAST(@first AS INT) AS first_val;
  "))
  seq(from = stell_range$first_val, length.out = n)
}

### check and retrieve the necessary amount of new ids

check_stellenid <- function(new_data, old_data, conn){
  new_data_wsid = new_data %>% filter(!is.na(stellen_id)) %>% select(-VZÄ_unbek)# neue Stellen mit ID (übernommen)
  new_data_wosid = new_data %>% filter(is.na(stellen_id)) %>% select(-VZÄ_unbek) # neue Stellen ohne ID (frisch)

  new_data_wsid_t0 <- new_data_wsid %>% inner_join(old_data, by = join_by( # nearly zero-tolerance -> nur Anzahl, Besetzt und Kommentare dürfen sich geändert haben
    Bundesland == bdl, Versorgungsregion == VRG, Gemeinde == gemeinde, Bezirk == bezirk, # main-criteria - sind die noch drin?
    Ort == Ort, System == syst, Kassen == kassen, Vertragsart == vertragsart, Fach == fach, # main-criteria - sind die noch drin?
    Förderung == förderung, Hausapotheke == hapo,  # Status == stat,
    Äquivalent == äqui, stellen_id == stellen_id)) %>%
    filter(Status == stat | (stat == "Neu" & Status != "Neu")) %>%
    select(ID, Änderungsdatum,Bundesland,Jahr,Quartal,Gemeinde,Ort,Bezirk,Versorgungsregion,System,Kassen,Kassen_Kommentar,Vertragsart,Vertrag_Kommentar,Fach,
           Förderung,Hausapotheke,Status,Status_Kommentar,Anzahl,Besetzt,Äquivalent,Löschen,stellen_id)

  ## diese können mit der alten id übernommen werden

  new_data_wsid_t1 <- anti_join(new_data_wsid, new_data_wsid_t0, by = join_by(
    Bundesland == Bundesland, Versorgungsregion == Versorgungsregion, Gemeinde == Gemeinde, Bezirk == Bezirk,
    Ort == Ort, System == System, Kassen == Kassen, Vertragsart == Vertragsart, Fach == Fach,
    Förderung == Förderung, Hausapotheke == Hausapotheke, Besetzt == Besetzt,
    Status == Status, Äquivalent == Äquivalent, stellen_id == stellen_id)) %>%
    mutate(stellen_id = NA_integer_) %>%
    select(ID, Änderungsdatum,Bundesland,Jahr,Quartal,Gemeinde,Ort,Bezirk,Versorgungsregion,System,Kassen,Kassen_Kommentar,Vertragsart,Vertrag_Kommentar,Fach,
           Förderung,Hausapotheke,Status,Status_Kommentar,Anzahl,Besetzt,Äquivalent,Löschen,stellen_id)

  ## für die könnten wir eine neue Stellen-ID generieren und eine Warnmeldung für den USer zurückgeben, dass diese Stelle mit der ID "xyz" einer neuen Stellen-ID
  # zugewiesen wurde

  n_newids = nrow(new_data_wsid_t1) + nrow(new_data_wosid)

  if(n_newids > 0){

    new_data_wnsid = rbind(new_data_wsid_t1, new_data_wosid)

    new_ids <- get_new_stellen_id_range(conn = conn, n = n_newids)
    new_data_wnsid$stellen_id <- new_ids

    data_stellenids_checked <- rbind(new_data_wsid_t0, new_data_wnsid)

  } else {
    data_stellenids_checked <- new_data_wsid_t0
  }


}




