# Helper - Funnktion für die Label-erstellung
collapse_popups <- function(df){
  vec = c()
  for(i in seq_len(nrow(df))){
    item <- paste(unlist(df[i,2]), collapse= ", ")
    vec <- append(vec, item)
  }
  return(vec)
}


### Funktion zum erstellen der Popup-Texte für Punkte / Heatmaps
build_popups <- function(reg_level, data_df){
  data_df <- as.data.frame(data_df)
  data_df <- data_df %>% select(fach, anzahl, äqui, anzahl_besetzt, stat, vertragsart, reg_level) %>% unique()

  if(nrow(data_df) > 0){

    Fächer <- aggregate(fach ~ data_df[[reg_level]], data = data_df, FUN = paste)
    Fächer$fach <- collapse_popups(Fächer)

    Anzahl <- aggregate(as.character(anzahl) ~ data_df[[reg_level]], data = data_df, FUN = paste)
    Anzahl$zahl <- collapse_popups(Anzahl)

    Äqui <- aggregate(as.character(äqui) ~ data_df[[reg_level]], data = data_df, FUN = paste)
    Äqui$äqu <- collapse_popups(Äqui)

    Besetzt <- aggregate(as.character(anzahl_besetzt) ~ data_df[[reg_level]], data = data_df, FUN = paste)
    Besetzt$zahl_bes <- collapse_popups(Besetzt)

    Status <- aggregate(stat ~ data_df[[reg_level]], data = data_df, FUN = paste)
    Status$status <- collapse_popups(Status)

    Vertragsart <- aggregate(vertragsart ~ data_df[[reg_level]], data = data_df, FUN = paste)
    Vertragsart$va <- collapse_popups(Vertragsart)

    paste_df <- cbind(Fächer, Anzahl, Anzahl, Äqui, Besetzt, Status, Vertragsart)

  } else {
    paste_df = data.frame(fach = NA_character_, zahl = NA_character_, äqu = NA_character_, zahl_bes = NA_character_, status = NA_character_,
                          va = NA_character_)

  }
  return(paste_df)
}
