setShapeStyle <- function(map, data, layerId, group,
                           color = NULL, weight = NULL, opacity = NULL,
                           fill = NULL, fillColor = NULL, fillOpacity = NULL,
                           dashArray = NULL, stroke = NULL, # brauchen wir die beiden überhaupt?
                           smoothFactor = NULL, noClip = NULL, label = NULL,
                           options = NULL){

  options <- c(list(data = data, layerId = layerId, group = group),
               options,
               filterNULL(list(stroke = stroke, color = color,
                               weight = weight, opacity = opacity,
                               fill = fill, fillColor = fillColor,
                               fillOpacity = fillOpacity, dashArray = dashArray,
                               smoothFactor = smoothFactor, noClip = noClip, label = label
               )))
  options <- evalFormula(options, data = data)
  options <- do.call(data.frame, c(options, list(stringsAsFactors=FALSE)))

  layerId <- options[[1]]
  style <- options[-1]

  if("label" %in% colnames(style)){
    labelData = style[,"label", FALSE]
    style = style[,-which(colnames(style)=="label"), FALSE]
    leaflet::invokeMethod(map, data, "setLabel", "shape", layerId, label, group)
  }
  leaflet::invokeMethod(map, data, "setStyle", "shape", layerId, style, group);
}

