################### funktion, um den perc-change zu berechnen (map, aber potenziell wiederverwendbar) #####################

compute_percentage_diff <- function(quartal_akt, jahr_akt, einheit_region, id, Quartal_mapping, data_kas){

  quartal_bef <- Quartal_mapping$Before[match(quartal_akt, Quartal_mapping$Quartal)]

  if(quartal_bef == "1. Quartal"){
    jahr_akt <- as.character((as.integer(jahr_akt)-1))
  }

  if(einheit_region == "vrg"){
    reg <- "VRGCode"
  } else if(einheit_region == "gemeinde"){
    reg <- "gemeinde_code"
  } else { reg <- "bez_code" }

  anzahl_bef <- data_kas %>% filter(.[[reg]] == id, quartal == quartal_bef, jahr == jahr_akt) %>% group_by(.[[reg]]) %>% summarise(stellen = sum(anzahl_unbesetzt)) %>% ungroup() %>%
    as.data.frame() %>% unique() %>% pull(stellen)
  anzahl_akt <- data_kas %>% filter(.[[reg]] == id, quartal == quartal_akt, jahr == jahr_akt) %>% group_by(.[[reg]]) %>% summarise(stellen = sum(anzahl_unbesetzt)) %>% ungroup() %>%
    as.data.frame() %>% unique() %>% pull(stellen)


  if( length(anzahl_bef) == 0 | length(anzahl_akt) == 0){
    if(length(anzahl_bef) > length(anzahl_akt)) {
      if(anzahl_bef == 0){
        perc_change <- 0
      } else { perc_change <- -100 }
    } else if(length(anzahl_bef) < length(anzahl_akt)){
      if(anzahl_akt == 0){
        perc_change = 0
      } else {perc_change <- 100}
    } else {
      perc_change <- 0
    }
  } else {
    perc_change <- round(((anzahl_akt-anzahl_bef)/anzahl_bef)*100)
  }

  return(perc_change)
}


