js_return_click <- function(idpassword, idbutton) {
  glue::glue(.open = "{{{", .close = "}}}", '
	  $(document).keyup(function(event) {
    if ($("#{{{idpassword}}}").is(":focus") && (event.keyCode == 13)) {
        $("#{{{idbutton}}}").click();
    }
    });')
}

