#' login Server Functions
#'
#' @noRd
mod_login_server <- function(id, connex, log_out = shiny::reactiveVal(), reload_on_logout = T, cookie_logins = FALSE) {

  library(odbc)
  library(DBI)
  library(shiny)
  library(dplyr)

  #connex <- dbConnect(odbc::odbc(), DSN = .z, UID = .x, PWD = .y)

  ## man könnte am SQL-Server ein automatisches Skript ausführen, dass die Passwörter gleich dort entcryptet?
  # und das dann nur ausführen - Frage ist halt nur, ob man dann auch tatsächlich was zurückbekommen könnte?
  moduleServer(id, function(input, output, session){
  ns <- session$ns

  credentials <- reactiveValues(user_auth = FALSE, info = NULL, cookie_already_checked = FALSE)
  val <- reactiveVal()

  shiny::observeEvent(log_out(), {
    if (cookie_logins) {
      shinyjs::js$rmcookie()
    }
    if (reload_on_logout) {
      session$reload()
    } else {
      shiny::updateTextInput(session, "password", value = "")
      credentials$user_auth <- FALSE
      credentials$info <- NULL
    }
  })

  shiny::observe({
    if (credentials$user_auth) {
      shinyjs::hide(id = "panel")
    } else {
      shinyjs::toggle(id = "panel", condition = !credentials$user_auth)
    }
  })


  observeEvent(input$button, {
    ## validate input strings:

    if(typeof(input$user_name) == "character" && typeof(input$password) == "character"){
      if(length(input$user_name) < 7 & length(input$password) <= 12) {
        u = input$user_name
        p = input$password

        val <- load_data_credentials(u,p)
        #sql_command <- glue::glue_sql("EXECUTE compare_passwords @uids = {`u`}, @pwds = {`p`}", .con = connex)
        #val <- dbGetQuery(connex, sql_command)
        val(req)
        if(length(nrow(val)) > 0){
          credentials$user_auth <- TRUE
          credentials$info <- val$permission
        } else {
            shinyjs::toggle(id = "error", anim = TRUE, time = 1, animType = "fade")
            shinyjs::delay(5000, shinyjs::toggle(id = "error", anim = TRUE, time = 1, animType = "fade"))
        }
      } else {
        shinyjs::toggle(id = "error", anim = TRUE, time = 1, animType = "fade")
        shinyjs::delay(5000, shinyjs::toggle(id = "error", anim = TRUE, time = 1, animType = "fade"))
      }
    } else {
      shinyjs::toggle(id = "error", anim = TRUE, time = 1, animType = "fade")
      shinyjs::delay(5000, shinyjs::toggle(id = "error", anim = TRUE, time = 1, animType = "fade"))
    }
  })

  # return reactive list containing auth boolean and user information
  shiny::reactive({
    shiny::reactiveValuesToList(credentials)
  })
})
}

