logoutServer <- function(id, active, ...) {
  moduleServer(
    id,
    function (input, output, session) {
      shiny::observe({
        shinyjs::toggle(id = "button", condition = active(), ...)
      })

      # return reactive logout button tracker
      shiny::reactive({
        input$button
      })
    }
  )
