  overflow-y: auto !important;
  overflow-x: auto !important;
  height: auto !important;
}

.htContextMenu .wtHolder::-webkit-scrollbar {
  display: none;
}

/* ==========================================================
   ERROR HIGHLIGHTING — must come LAST to win specificity
   ========================================================== */
.handsontable .ht_master tr:nth-child(odd) td.Fehler,
.handsontable .ht_master tr:nth-child(even) td.Fehler,
.handsontable .ht_master tr:nth-child(odd) td.Fehler.current,
.handsontable .ht_master tr:nth-child(even) td.Fehler.current,
.handsontable .ht_master tr:nth-child(odd) td.Fehler.area,
.handsontable .ht_master tr:nth-child(even) td.Fehler.area {
  /*background-color: #FF746C !important; */
  border: 2px solid #DB5856 !important;
}

table.dataTable thead th[data-is-resizable=true] {
  border-inline-start: 1px solid transparent;
  border-inline-end: 1px dashed #bfbfbf;
}
table.dataTable thead th.dt-colresizable-hover {
  cursor: col-resize !important;
  background-color: #eaeaea;
  border-inline-start: 1px solid #bfbfbf;
 }
table.dataTable thead th.dt-colresizable-bound-min,
table.dataTable thead th.dt-colresizable-bound-max {
  opacity: 0.2;
  cursor: not-allowed !important;
}

table.dataTable thead th.dt-colresizable-hover {
  cursor: col-resize !important;
}

@media (hover: none) and (pointer: coarse) {
  table.dataTable thead th[data-is-resizable=true] {
    border-inline-end: 3px solid #808080 !important;
  }
  table.dataTable thead th[data-is-resizable=true] {
    position: relative;
  }
  table.dataTable thead th[data-is-resizable=true]::after {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    inset-inline-end: -8px;
    width: 16px;
  }
}

