        }

        let init = settings.oInit.colResize;
        let defaults = DataTable.defaults.colResize;

        if (init || defaults) {
            let opts = $.extend({}, init, defaults);

            if (init !== false) {
                new ColResize(settings, opts);
            }
        }
    });

    // API augmentation
    $.fn.dataTable.Api.register('colResize.enable()', function () {
        return this.iterator('table', function (ctx) {
            ctx._colResize.fnEnable();
        });
    });
    $.fn.dataTable.Api.register('colResize.disable()', function () {
        return this.iterator('table', function (ctx) {
            ctx._colResize.fnDisable();
        });
    });
    $.fn.dataTable.Api.register('colResize.reset()', function () {
        return this.iterator('table', function (ctx) {
            ctx._colResize.fnReset();
        });
    });
    $.fn.dataTable.Api.register('colResize.save()', function () {
        return this.iterator('table', function (ctx) {
            ctx._colResize.fnSaveState();
        });
    });
    $.fn.dataTable.Api.register('colResize.restore()', function () {
        return this.iterator('table', function (ctx) {
            ctx._colResize.fnRestoreState();
        });
    });
}));

Shiny.addCustomMessageHandler("capture_map", function(msg) {

  const container = document.getElementById("map-container");
  const rect      = container.getBoundingClientRect();
  const W         = rect.width;
  const H         = rect.height;

  //console.log(rect.left);
  //console.log(rect.top);


  // ── Step 1: read & neutralise the map pane transform ──────────────────────
  const mapPane       = container.querySelector(".leaflet-map-pane");
  const mapTransform  = mapPane.style.transform
    .replace("translate3d(", "").split(",");
  const mapX = parseFloat(mapTransform[0]);
  const mapY = parseFloat(mapTransform[1]);
  //mapPane.style.transform = "translate3d(0px, 0px, 0px)";
  //console.log(mapX);
  //console.log(mapY);


  // ── Step 2: shift every tile by the map pane offset ───────────────────────
  const myTiles  = Array.from(container.querySelectorAll("img.leaflet-tile"));
 // console.log(myTiles)
  const tilesLeft = [];
  const tilesTop  = [];
  myTiles.forEach(function(tile, i) {
    tilesLeft[i] = parseFloat(tile.style.left);
    tilesTop[i]  = parseFloat(tile.style.top);
    tile.style.left = (tilesLeft[i] - mapX) + "px"; //0 + "px";
    tile.style.top  = (tilesTop[i] - mapY) + "px";  //0 + "px";
  });

  // ── Step 4: shift the SVG layer ────────────────────────────────────────────
  const svgLayer = container.querySelector("svg.leaflet-zoom-animated");
  //console.log(svgLayer);
  let linesX = 0, linesY = 0;
  if (svgLayer) {
    const linesTransform = svgLayer.style.transform
      .replace("translate3d(", "").split(",");
    linesX = parseFloat(linesTransform[0]) || 0;
    linesY = parseFloat(linesTransform[1]) || 0;

   // console.log(linesX);
    //console.log(linesY);

   // console.log(linesX-mapX+157); //Offset
    // console.log(linesY-mapY+81);

    // const offsetX = (linesX-mapX+157);
    // const offsetY = (linesY-mapY+81);

    //svgLayer.style.transform = "translate3d(" (linesX-mapX) "px, " +  (linesY-mapY) + "px, 0px)";
    svgLayer.style.transform = "translate3d(0px, 0px, 0px)"
    //svgLayer.style.transform = "translate3d(-78px ,-43px, 0px)";
    //svgLayer.style.transform = "translate3d(" + 0 + "px, " + //(mapX)(mapY)
                                              //0 + "px, 0px)";
  }
  const vb = svgLayer.getAttribute('viewBox').split(' ');
  svgLayer.setAttribute('viewBox', `0 0 ${vb[2]} ${vb[3]}`);

  // ── Step 5: capture ────────────────────────────────────────────────────────
  setTimeout(function() {
    html2canvas(container, {

      useCORS:     true,
      allowTaint:  true,
      scale:       2,
      x:           rect.left-25,
      y:           rect.top-80,
      width:       W,
      height:      H,
      scrollX: window.scrollX,
      scrollY: window.scrollY,
      windowWidth:  window.innerWidth,
      windowHeight: window.innerHeight
    }).then(function(canvas) {

      // ── Step 6: restore everything ────────────────────────────────────────
       mapPane.style.transform = "translate3d(" + mapX + "px, " + mapY + "px, 0px)";

      myTiles.forEach(function(tile, i) {
        tile.style.left = tilesLeft[i] + "px";
        tile.style.top  = tilesTop[i]  + "px";
     });

      if (svgLayer) {
        svgLayer.style.transform = "translate3d(" + linesX + "px, " + linesY + "px, 0px)";
        svgLayer.setAttribute('viewBox', vb.join(' '));
      }

      // ── Step 7: export ────────────────────────────────────────────────────
      if (msg.format === "png") {
        const link    = document.createElement("a");
        link.download = "map.png";
        link.href     = canvas.toDataURL("image/png");
        link.click();

      } else if (msg.format === "pdf") {
        const { jsPDF } = window.jspdf;
        const imgData   = canvas.toDataURL("image/png");
        const pdf = new jsPDF({
          orientation: W > H ? "landscape" : "portrait",
          unit:        "px",
          format:      [W, H]
        });
        pdf.addImage(imgData, "PNG", 0, 0, W, H);
        pdf.save("map.pdf");
      }
    });
  }, 400);
});

Shiny.addCustomMessageHandler("download_leaflet_map", function(message) {
  console.log("mapshot.js loaded");

  var mapEl = document.getElementById("map_1-map");

  if (mapEl === null || typeof mapEl === "undefined") {
    console.log("Map element not found or undefined");
  } else {
    console.log("Map element exists:", mapEl);
  }

  // Workaround: ensure Leaflet tiles are fully loaded
  var tilesLoaded = Array.from(mapEl.querySelectorAll(".leaflet-tile")).every(t => t.complete);

  if (!tilesLoaded) {
    setTimeout(function() {
      Shiny.onInputChange("retry_download", Math.random());
    }, 500);
    return;
  }

  // Use dom-to-image to convert map div to PNG
  html2canvas(mapEl, {useCORS: true, scale: 2, backgroundColor: null}).then(function(canvas) {
      var link = document.createElement('a');
      link.download = "map.png";
      link.href = canvas.toDataURL("image/png");
      link.click();
    })
    .catch(function(err) {
      console.error("Map download failed:", error);
      alert("Failed to generate PNG. Try again.");
    });

});
